import json

CURRENT = "2026-07-28"
LEGACY = "2025-11-25"

def modern_request(request_id, method, params, client_name="support-console"):
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "method": method,
        "params": {
            **params,
            "_meta": {
                "io.modelcontextprotocol/protocolVersion": CURRENT,
                "io.modelcontextprotocol/clientInfo": {"name": client_name, "version": "1.0"},
            },
        },
    }

# The modern protocol has no initialize/initialized handshake.
call = modern_request(1, "tools/call", {"name": "search", "arguments": {"q": "policy"}})
print(json.dumps(call, indent=2))

# Older servers still use initialize and a negotiated handshake version.
legacy_initialize = {
    "jsonrpc": "2.0", "id": 2, "method": "initialize",
    "params": {"protocolVersion": LEGACY, "capabilities": {},
               "clientInfo": {"name": "support-console", "version": "1.0"}},
}
print(json.dumps(legacy_initialize, indent=2))

MODERN = "2026-07-28"
LEGACY = {"2025-11-25", "2025-06-18", "2025-03-26"}

def route_request(request):
    version = request.get("headers", {}).get("MCP-Protocol-Version")
    if version == MODERN:
        # Modern requests are self-contained; no per-session initialize state.
        return {"era": "stateless", "method": request["body"]["method"]}
    if version in LEGACY:
        # Legacy clients negotiate once with initialize and keep a session.
        return {"era": "handshake", "method": request["body"]["method"]}
    raise ValueError("Unsupported MCP protocol version")

modern = {"headers": {"MCP-Protocol-Version": MODERN},
          "body": {"jsonrpc": "2.0", "id": 1, "method": "tools/call"}}
print(route_request(modern))

from dataclasses import dataclass

@dataclass(frozen=True)
class Entry:
    name: str
    protocol: str
    owner: str
    tested: bool

SUPPORTED = {"2026-07-28", "2025-11-25", "2025-06-18"}

def admit(entry):
    if not entry.owner:
        return "reject", "unowned server"
    if entry.protocol not in SUPPORTED:
        return "reject", "unsupported protocol version"
    if not entry.tested:
        return "canary", "compatibility evidence required"
    return "admit", "tested version and owner recorded"

print(admit(Entry("documents", "2026-07-28", "platform-team", True)))
